local _, ns = ...

-- The options panel: a stevio-ui entry in Blizzard's Options -> AddOns with a
-- page per module (generated by Editor.lua), a General page (modules on/off,
-- style, layout, reset) and pages for the keybinding and CVar overrides.
-- Everything saved here lives in StevioUIConfig, account-wide.

local Overrides = ns.Overrides
local Editor = ns.ConfigEditor
local config = ns.config.settings

local T = ns.T

-- Module pages in sidebar order: config key and title.
local MODULES = {
	{ "units", "Unit frames", "Einheitenfenster" },
	{ "group", "Group grid", "Gruppenraster" },
	{ "keyboardHealing", "Keyboard healing", "Tastaturheilung" },
	{ "actionbars", "Action bars", "Aktionsleisten" },
	{ "minimap", "Minimap", "Minikarte" },
	{ "tooltip", "Tooltip", "Tooltip" },
	{ "auras", "Auras", "Auren" },
	{ "tracker", "Objective tracker", "Questverfolgung" },
	{ "chat", "Chat", "Chat" },
	{ "lootTicker", "Loot ticker", "Beuteticker" },
	{ "notch", "Notch", "Notch" },
	{ "questRewards", "Quest rewards", "Questbelohnungen" },
	{ "accessibility", "Quickjump", "Schnellsprung" },
	{ "settings", "Profile", "Profil" },
}

local RESET_DIALOG = "STEVIOUI_RESET_CONFIG"

StaticPopupDialogs[RESET_DIALOG] = {
	text = T(
		"Reset all stevio-ui options to the defaults in code and reload the UI?",
		"Alle stevio-ui-Optionen auf die Vorgaben im Code zurücksetzen und das UI neu laden?"
	),
	button1 = YES,
	button2 = NO,
	OnAccept = function()
		StevioUIConfig.values, StevioUIConfig.bindings, StevioUIConfig.cvars = {}, {}, {}
		ReloadUI()
	end,
	timeout = 0,
	whileDead = true,
	hideOnEscape = true,
}

local function CreateButton(parent, text, width)
	local button = CreateFrame("Button", nil, parent, "UIPanelButtonTemplate")
	button:SetSize(width, 22)
	button:SetText(text)
	return button
end

local function CreateInput(parent, width)
	local input = CreateFrame("EditBox", nil, parent, "InputBoxTemplate")
	input:SetSize(width, 20)
	input:SetAutoFocus(false)
	input:SetScript("OnEnterPressed", input.ClearFocus)
	input:SetScript("OnEscapePressed", input.ClearFocus)
	return input
end

local function CreateGeneralPage()
	local sections = {}
	for _, module in ipairs(MODULES) do
		if module[1] ~= "settings" and ns.config[module[1]] and ns.config[module[1]].enabled ~= nil then
			sections[#sections + 1] = {
				path = { "config", module[1], "enabled" },
				label = ns.isGerman and module[3] or module[2],
			}
		end
	end
	sections[#sections + 1] = { path = { "config", "style" } }
	sections[#sections + 1] = { path = { "layout" } }

	return Editor.CreatePage("stevio-ui", sections, function(page, top)
		local reset = CreateButton(page, T("Reset all options", "Alle Optionen zurücksetzen"), 200)
		reset:SetPoint("TOPLEFT", 16, -top)
		reset:SetScript("OnClick", function()
			StaticPopup_Show(RESET_DIALOG)
		end)
		local hint = page:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		hint:SetPoint("LEFT", reset, "RIGHT", 10, 0)
		hint:SetText(
			T(
				"Changed values are highlighted; keybindings and graphics changed in Blizzard's menus are kept too.",
				"Geänderte Werte sind hervorgehoben; in Blizzards Menüs geänderte Tasten und Grafik bleiben auch."
			)
		)
		return 30
	end)
end

-- Keybindings -----------------------------------------------------------------

-- A list of override rows for a flat map (key -> command, CVar -> value).
local function CreateListPage(title, extra, fillRow)
	local page = CreateFrame("Frame")
	page.rows = {}
	local heading = page:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
	heading:SetPoint("TOPLEFT", 16, -16)
	heading:SetText(title)
	local top = 44 + extra(page, 44)

	local scroll = CreateFrame("ScrollFrame", nil, page, "UIPanelScrollFrameTemplate")
	scroll:SetPoint("TOPLEFT", 16, -top)
	scroll:SetPoint("BOTTOMRIGHT", -32, 12)
	page.content = CreateFrame("Frame", nil, scroll)
	page.content:SetSize(1, 1)
	scroll:SetScrollChild(page.content)
	scroll:SetScript("OnSizeChanged", function(_, width)
		page.content:SetWidth(width)
	end)

	function page:Render(entries)
		for index, entry in ipairs(entries) do
			local row = self.rows[index]
			if not row then
				row = CreateFrame("Frame", nil, self.content)
				row:SetHeight(24)
				row:SetPoint("TOPLEFT", 0, -(index - 1) * 24)
				row:SetPoint("RIGHT")
				row.name = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
				row.name:SetPoint("LEFT")
				row.name:SetWidth(180)
				row.name:SetJustifyH("LEFT")
				row.value = row:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
				row.value:SetPoint("LEFT", 190, 0)
				row.value:SetWidth(240)
				row.value:SetJustifyH("LEFT")
				self.rows[index] = row
			end
			fillRow(self, row, entry)
			row:Show()
		end
		for index = #entries + 1, #self.rows do
			self.rows[index]:Hide()
		end
		self.content:SetHeight(math.max(#entries * 24, 1))
	end
	return page
end

local function SortedKeys(map)
	local keys = {}
	for key in pairs(map) do
		keys[#keys + 1] = key
	end
	table.sort(keys)
	return keys
end

-- Sets (or with `command` nil, unbinds) `key` as an override and applies it.
local function SetBindingOverride(key, command)
	local profileCommand = (config.profile.bindings or {})[key]
	if command == profileCommand then
		StevioUIConfig.bindings[key] = nil
	elseif command == nil then
		StevioUIConfig.bindings[key] = profileCommand and false or nil
	else
		StevioUIConfig.bindings[key] = command
	end
	ns.ApplyOverridesNow()
end

local function BindingLabel(command)
	if command == false then
		return T("(unbound)", "(nicht belegt)")
	end
	return GetBindingName(command)
end

-- Blizzard's binding list, grouped by its categories, as a menu.
local function ChooseAction(owner, onChoose)
	MenuUtil.CreateContextMenu(owner, function(_, root)
		root:SetScrollMode(500)
		root:CreateButton(T("(unbind)", "(Belegung entfernen)"), function()
			onChoose(nil)
		end)
		local submenus = {}
		for index = 1, GetNumBindings() do
			local command, category = GetBinding(index)
			if command and not command:find("^HEADER") then
				local categoryName = category and _G[category] or category or OTHER
				local submenu = submenus[categoryName]
				if not submenu then
					submenu = root:CreateButton(categoryName)
					submenu:SetScrollMode(500)
					submenus[categoryName] = submenu
				end
				submenu:CreateButton(GetBindingName(command), function()
					onChoose(command)
				end)
			end
		end
	end)
end

-- Waits for the next key (with modifiers) on `button`; Escape cancels.
local function CaptureKey(button, onKey)
	local text = button:GetText()
	button:SetText(T("Press a key", "Taste drücken"))
	button:EnableKeyboard(true)
	button:SetPropagateKeyboardInput(false)
	button:SetScript("OnKeyDown", function(self, key)
		if IsMetaKey and IsMetaKey(key) then
			return
		end
		self:EnableKeyboard(false)
		self:SetScript("OnKeyDown", nil)
		self:SetText(text)
		if key ~= "ESCAPE" then
			onKey(CreateKeyChordStringUsingMetaKeyState(key))
		end
	end)
end

local function CreateBindingsPage()
	local page
	page = CreateListPage(T("Keybindings", "Tastenbelegung"), function(self, top)
		local add = CreateButton(self, T("Add binding", "Taste belegen"), 160)
		add:SetPoint("TOPLEFT", 16, -top)
		add:SetScript("OnClick", function(button)
			CaptureKey(button, function(key)
				ChooseAction(button, function(command)
					SetBindingOverride(key, command)
					page:Refresh()
				end)
			end)
		end)
		local hint = self:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		hint:SetPoint("LEFT", add, "RIGHT", 10, 0)
		hint:SetText(
			T(
				"Keys that differ from Profile.lua. Changes in Blizzard's Keybindings menu show up here too.",
				"Tasten, die von Profile.lua abweichen. Änderungen in Blizzards Tastenbelegung erscheinen auch hier."
			)
		)
		return 30
	end, function(self, row, key)
		row.name:SetText(key)
		row.value:SetText(BindingLabel(StevioUIConfig.bindings[key]))
		if not row.action then
			row.action = CreateButton(row, T("Action", "Aktion"), 80)
			row.action:SetPoint("LEFT", 440, 0)
			row.remove = CreateButton(row, "x", 24)
			row.remove:SetPoint("LEFT", row.action, "RIGHT", 4, 0)
		end
		row.action:SetScript("OnClick", function(button)
			ChooseAction(button, function(command)
				SetBindingOverride(key, command)
				self:Refresh()
			end)
		end)
		row.remove:SetScript("OnClick", function()
			-- Back to what Profile.lua binds there.
			SetBindingOverride(key, (config.profile.bindings or {})[key])
			self:Refresh()
		end)
	end)
	function page:Refresh()
		self:Render(SortedKeys(StevioUIConfig.bindings))
	end
	page:SetScript("OnShow", page.Refresh)
	return page
end

-- CVars -----------------------------------------------------------------------

-- Sets `name` to `value` as an override (nil removes it) and applies it.
local function SetCVarOverride(name, value)
	local profileValue = (config.profile.cvars or {})[name]
	if value == nil or value == profileValue then
		StevioUIConfig.cvars[name] = nil
	else
		StevioUIConfig.cvars[name] = value
	end
	-- A CVar outside the profile is no longer managed: back to the game default.
	if value == nil and profileValue == nil then
		ns.ApplyOverridesNow(name, C_CVar.GetCVarDefault(name))
	else
		ns.ApplyOverridesNow()
	end
end

local function IsSettableCVar(name)
	local value, _, _, _, isLocked, isSecure, isReadOnly = C_CVar.GetCVarInfo(name)
	return value ~= nil and not isLocked and not isSecure and not isReadOnly
end

local function CreateCVarsPage()
	local page
	page = CreateListPage(T("Graphics & interface", "Grafik & Interface"), function(self, top)
		local name = CreateInput(self, 200)
		name:SetPoint("TOPLEFT", 22, -top)
		local value = CreateInput(self, 120)
		value:SetPoint("LEFT", name, "RIGHT", 12, 0)
		local add = CreateButton(self, T("Set", "Setzen"), 80)
		add:SetPoint("LEFT", value, "RIGHT", 8, 0)
		local hint = self:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		hint:SetPoint("LEFT", add, "RIGHT", 10, 0)
		hint:SetText(T("CVar name and value", "CVar-Name und Wert"))
		add:SetScript("OnClick", function()
			local cvar = name:GetText():match("^%s*(.-)%s*$")
			if cvar == "" or not IsSettableCVar(cvar) then
				hint:SetText(T("Unknown or protected CVar", "Unbekannte oder geschützte CVar"))
				return
			end
			SetCVarOverride(cvar, value:GetText())
			name:SetText("")
			value:SetText("")
			hint:SetText(T("CVar name and value", "CVar-Name und Wert"))
			page:Refresh()
		end)
		return 30
	end, function(self, row, cvar)
		row.name:SetText(cvar)
		row.value:SetText(StevioUIConfig.cvars[cvar])
		if not row.remove then
			row.remove = CreateButton(row, "x", 24)
			row.remove:SetPoint("LEFT", 440, 0)
		end
		row.remove:SetScript("OnClick", function()
			SetCVarOverride(cvar, nil)
			self:Refresh()
		end)
	end)
	function page:Refresh()
		self:Render(SortedKeys(StevioUIConfig.cvars))
	end
	page:SetScript("OnShow", page.Refresh)
	return page
end

-- Setup -----------------------------------------------------------------------

local rootCategory

function ns.SetupOptionsPanel()
	rootCategory = Settings.RegisterCanvasLayoutCategory(CreateGeneralPage(), "stevio-ui")
	for _, module in ipairs(MODULES) do
		if ns.config[module[1]] then
			local page = Editor.CreatePage(ns.isGerman and module[3] or module[2], {
				{ path = { "config", module[1] } },
			})
			-- The module's own table opens expanded.
			page.collapsed[Overrides.Encode({ "config", module[1] })] = false
			Settings.RegisterCanvasLayoutSubcategory(rootCategory, page, ns.isGerman and module[3] or module[2])
		end
	end
	Settings.RegisterCanvasLayoutSubcategory(rootCategory, CreateBindingsPage(), T("Keybindings", "Tastenbelegung"))
	Settings.RegisterCanvasLayoutSubcategory(
		rootCategory,
		CreateCVarsPage(),
		T("Graphics & interface", "Grafik & Interface")
	)
	Settings.RegisterAddOnCategory(rootCategory)

	ns:RegisterSlashCommand("config", function()
		Settings.OpenToCategory(rootCategory:GetID())
	end)
	ns:RegisterSlashCommand("reset", function()
		StaticPopup_Show(RESET_DIALOG)
	end)
end
